def main():
    parser = argparse.ArgumentParser(
        description="Döntési lezárás: szoba pontozása + top 3 ötlet → Gitea issue"
    )
    parser.add_argument("--room-id", required=True, help="A lezárandó szoba azonosítója")
    parser.add_argument("--gitea-url", default=os.environ.get("GITEA_URL", ""), help="Gitea base URL")
    parser.add_argument("--gitea-token", default=os.environ.get("GITEA_TOKEN", ""), help="Gitea API token")
    parser.add_argument("--owner", default=os.environ.get("GITEA_OWNER", ""), help="Gitea repó owner")
    parser.add_argument("--repo", default=os.environ.get("GITEA_REPO", ""), help="Gitea repó neve")
    parser.add_argument("--top-n", type=int, default=3, help="Hány top ötletet exportáljunk (default: 3)")
    parser.add_argument("--dry-run", action="store_true", help="Nem küld valódi Gitea requestet")
    parser.add_argument("--seed-demo", action="store_true", help="Demó szoba feltöltése példa ötletekkel")
    parser.add_argument("--storage", default="data/rooms.json", help="Szoba tároló fájl útvonala")
    args = parser.parse_args()

    # Tároló inicializálása
    store = RoomStore(storage_path=args.storage)

    # Opcionális demó adatok
    if args.seed_demo:
        seed_demo_room(store, args.room_id)

    # Gitea creator (csak ha van URL + token, vagy dry-run)
    gitea_creator = None
    if args.dry_run or (args.gitea_url and args.gitea_token and args.owner and args.repo):
        gitea_creator = GiteaIssueCreator(
            base_url=args.gitea_url or "https://gitea.example.com",
            token=args.gitea_token or "dummy-token",
            owner=args.owner or "a2a-mesh",
            repo=args.repo or "ideas",
            dry_run=args.dry_run,
        )
    else:
        print("[Info] Nincs Gitea konfigurálva. Csak pontozás lesz végrehjtva.")
        print("       Gitea exporthoz add meg: --gitea-url, --gitea-token, --owner, --repo")
        print("       Vagy használj --dry-run flaget a szimulációhoz.\n")

    # Lezárás végrehajtása
    manager = ClosureManager(store, gitea_creator)
    result = manager.close_room_and_export(args.room_id, top_n=args.top_n)

    # Eredmény kiírása
    print(f"\n{'='*60}")
    print("LEZÁRÁS EREDMÉNYE")
    print(f"{'='*60}")
    print(json.dumps(result, ensure_ascii=False, indent=2))

    # Exit code
    if result.get("error"):
        sys.exit(1)
    sys.exit(0)


if __name__ == "__main__":
    main()